insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'el-guru', 'El Guru', array['youtube','tipster','creator']::listing_type[], 'Daily NBA player prop videos and live streams, with a free Discord.', 'El Guru posts NBA player prop picks on YouTube most days of the season, streams on Twitch and runs a free Discord for followers.', 'https://www.youtube.com/@elguru2025', 'free'::pricing_model, 'Free videos and a free Discord', array['nba']::text[], null, array['Free picks','Daily content','Discord community']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "About 6,700 subscribers, channel started May 2025. Videos are titled ''locks'' and the bio says ''the world''s greatest locksmith''; nothing is a lock, so keep that language off the listing. The Discord runs through Winible, so check for a paid tier. He also shares a Pikkit invite link, which I left off.", "feed_url": "https://www.youtube.com/feeds/videos.xml?channel_id=UCp50iqSF4XEOhbS2HmyvODA", "country": "US"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('El Guru')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('YouTube','https://www.youtube.com/@elguru2025'),('Twitch','https://twitch.tv/elguru2025'),('Discord','https://winible.com/elguru'),('TikTok','https://tiktok.com/@elgurustreams'),('Instagram','https://instagram.com/elgurulocks')) as v(platform,url) where l.slug = 'el-guru' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'bankroll-brian', 'BankrollBrian', array['youtube','tipster','creator']::listing_type[], 'Daily free picks and player props for NBA, NFL, MLB and WNBA.', 'BankrollBrian''s second YouTube channel, with daily videos covering free picks, predictions and player props across the NBA, WNBA, NFL and MLB. Paid picks are sold through Winible.', 'https://www.youtube.com/@Bankroll_Brian', 'freemium'::pricing_model, 'Free videos, with paid picks on Winible', array['nba','nfl','mlb']::text[], null, array['Free picks','Paid picks','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "About 11,300 subscribers. This is his second channel (started January 2026); find the main one and decide which to list. Video titles lead with winning runs and ''locks''; those are his own claims, so ask for a tracked record. Country not stated.", "feed_url": "https://www.youtube.com/feeds/videos.xml?channel_id=UCx9nbWRhWETVGZ1Au8FqoxQ"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('BankrollBrian')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('YouTube','https://www.youtube.com/@Bankroll_Brian'),('Winible','https://winible.com/bankrollbrian')) as v(platform,url) where l.slug = 'bankroll-brian' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'final-round-sports', 'Final Round Sports', array['youtube','tipster','creator']::listing_type[], 'Data-driven picks, props and breakdowns across NBA, NFL, MLB, WNBA and tennis.', 'A busy YouTube channel posting daily picks, player props and game breakdowns for the NBA, NFL, WNBA, MLB and tennis, with the numbers behind each play.', 'https://www.youtube.com/@Final_Round_Sports', 'free'::pricing_model, null, array['nba','nfl','mlb']::text[], null, array['Free picks','Write-ups with reasoning','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Established (about 76,600 subscribers, since 2020). His links page is titled ''Amazing Deals'', which usually means sportsbook or pick''em sign-up offers; open it and check before publishing.", "feed_url": "https://www.youtube.com/feeds/videos.xml?channel_id=UCyHwy6GwBufcf84tqNXj86w", "country": "US"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Final Round Sports')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('YouTube','https://www.youtube.com/@Final_Round_Sports'),('Links','https://beacons.ai/finalround')) as v(platform,url) where l.slug = 'final-round-sports' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'steadypicks', 'SteadyPicks', array['youtube','podcast','creator']::listing_type[], 'Betting shows and best bets across NFL, NBA and college football, powered by data.', 'SteadyPicks runs a network of betting shows on YouTube and as a podcast, with daily best bets and breakdowns for the NFL, NBA and college football from a team of hosts.', 'https://steadypicks.com', 'free'::pricing_model, 'Check whether paid picks are sold on the site', array['nfl','nba','ncaaf']::text[], null, array['Free picks','Daily content','Write-ups with reasoning']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "About 9,700 subscribers, since 2020. I did not open steadypicks.com, so check it for paid picks and sportsbook advertising.", "feed_url": "https://www.youtube.com/feeds/videos.xml?channel_id=UCLlMH3XkYUviUkkSJpwWX7w", "country": "US"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('SteadyPicks')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('Website','https://steadypicks.com'),('YouTube','https://www.youtube.com/@steadypicks'),('X','https://x.com/SteadyPicks'),('Instagram','https://instagram.com/steadypicks'),('TikTok','https://tiktok.com/@steadypicks'),('Apple Podcasts','https://podcasts.apple.com/us/podcast/steadypicks-radio-network-sports-betting-shows/id1555762459'),('Spotify','https://open.spotify.com/show/5QmANNS6NcGBfW7itkvogY')) as v(platform,url) where l.slug = 'steadypicks' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'lineups', 'Lineups', array['youtube','tool','news']::listing_type[], 'Free picks, props and DFS plays for NFL, NBA, NHL and MLB.', 'Lineups publishes daily videos with free picks, player props, DFS plays and fantasy advice across the NFL, NBA, NHL, MLB and college football. Its website adds lineups, projections and betting tools.', 'https://www.lineups.com', 'free'::pricing_model, null, array['nfl','nba','nhl','mlb','ncaaf']::text[], 'Fantasy tools', array['Free picks','Daily content','Projections']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "DECISION NEEDED: Lineups is tied to TheLines and features Legal Sports Report on its channel, which are sportsbook affiliate businesses. Expect heavy sportsbook sign-up promotion on the website. Same question as Before You Bet. About 54,300 subscribers, since 2017.", "feed_url": "https://www.youtube.com/feeds/videos.xml?channel_id=UCNg6eqiqndQ0xvAGHErP4FA", "country": "US", "categories": ["Fantasy tools"]}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Lineups')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('Website','https://www.lineups.com'),('YouTube','https://www.youtube.com/@Lineups'),('X','https://x.com/Lineups_US')) as v(platform,url) where l.slug = 'lineups' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'docs-sports', 'Doc''s Sports', array['youtube','tipster']::listing_type[], 'A long-running handicapping service with daily free picks and paid member selections.', 'Doc''s Sports posts daily free picks and predictions on YouTube across the NFL, college football, NBA, college basketball, MLB and NHL. The website sells premium member picks, with a free trial credit for new accounts.', 'https://www.docsports.com', 'freemium'::pricing_model, 'Free daily picks, with paid member picks and a free trial credit', array['nfl','ncaaf','nba','mlb','nhl']::text[], null, array['Free picks','Paid picks','Free trial','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Large channel (about 88,600 subscribers, since 2017). Old-style paid picks service, so treat any record as their own claim. I did not open docsports.com; check it for sportsbook advertising and confirm what the trial offer is.", "feed_url": "https://www.youtube.com/feeds/videos.xml?channel_id=UCbxXLZ-uHOY-QrsL1rMbXew", "country": "US"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Doc''s Sports')) on conflict (slug) do nothing;
