insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'hardwood-handicappers', 'Hardwood Handicappers', array['youtube','tipster','creator']::listing_type[], 'NBA best bets, prop ladders and award race updates.', 'A new basketball betting channel posting NBA best bets for each slate, player prop ladders and updates on award races such as Rookie of the Year.', 'https://www.youtube.com/@HardwoodHandicappers', 'free'::pricing_model, null, array['nba']::text[], null, array['Free picks','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Very small and new (about 470 subscribers, started November 2025), with no channel description or social links. Ask them for an X handle and a short blurb. Country not stated.", "feed_url": "https://www.youtube.com/feeds/videos.xml?channel_id=UCFU9fuMMn0EeQMdD8UddpcA"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Hardwood Handicappers')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('YouTube','https://www.youtube.com/@HardwoodHandicappers')) as v(platform,url) where l.slug = 'hardwood-handicappers' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
